#!/usr/bin/env bash
#
# A QA wizard walks a developer through every acceptance criterion of one
# feature, one stage at a time: open the page, do the steps, record pass or fail.
# Generated by /speckit.qa.walk from extensions/qa/scripts/qa-wizard.sh.
# Adapted from Matt Pocock's `wizard` skill (github.com/mattpocock/skills), MIT.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-check stages below the marker.
#
# Usage: ./qa-walk.sh [--only US1-2,EC-1] [--no-browser] [--reopen] [--results <path>]
#   --only       walk only these stage ids; other rows in the results file are kept
#   --no-browser print each URL instead of opening it
#   --reopen     open every URL again, even one already opened this run
#   --results    where the markdown results table goes (default: beside this script)

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

ONLY=""
NO_BROWSER="${NO_BROWSER:-}"
REOPEN=""
RESULTS=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    # A bare --only eats the next option as its value, so the filter matches no
    # stage and the walk reports success having checked nothing.
    --only)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--only needs a stage list' >&2; exit 2; }
      ONLY="$2"; shift 2 ;;
    --only=*)     ONLY="${1#*=}"; shift ;;
    --no-browser) NO_BROWSER=1; shift ;;
    --reopen)     REOPEN=1; shift ;;
    --results)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--results needs a path' >&2; exit 2; }
      RESULTS="$2"; shift 2 ;;
    --results=*)  RESULTS="${1#*=}"; shift ;;
    -h|--help)    sed -n '11,15p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) printf 'unknown option: %s\n' "$1" >&2; exit 2 ;;
  esac
done

# The last entry of BASH_SOURCE is the wizard itself, whether this library was
# copied into it or sourced from beside it, so the results land by the wizard.
_WIZARD="${BASH_SOURCE[$((${#BASH_SOURCE[@]} - 1))]}"
RESULTS="${RESULTS:-$(cd "$(dirname "$_WIZARD")" && pwd)/qa-walk-results.md}"

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
_STAGE_ID=""
_SKIPPING=""      # non-empty while --only excludes the current stage
RECORDS=()        # one tab-separated record per check: id, check, result, note
_SEEN=()          # every stage id this wizard declares, for the --only check
_OPENED=()        # every URL opened this run, so none is opened twice

# _clear wipes the terminal so only the current stage is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# _excluded ID succeeds when --only was given and does not name ID.
_excluded() {
  [[ -n "$ONLY" ]] || return 1
  [[ ",$ONLY," != *",$1,"* ]]
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser. This wizard tells you what to open and what to look\n' "$DIM"
  printf '  for, then records pass, fail or skip for each check. Stop any time with\n'
  printf '  Ctrl-C. Re-run with --only <id,...> to walk only the stages you name.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage ID "Title" clears the screen, announces the stage and shows progress.
# The id is the spec's own (US1-2, EC-1, SC-003) so results trace back to it.
stage() {
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  _STAGE_ID="$1"
  _SEEN+=("$1")
  if _excluded "$1"; then _SKIPPING=1; return 0; fi
  _SKIPPING=""
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$2" "$RESET"
}

# say "..." prints the Given: the state the check starts from.
say()  { [[ -n "$_SKIPPING" ]] || printf '  %s\n' "$1"; }
# step "..." is one action the developer takes: the When.
step() { [[ -n "$_SKIPPING" ]] || printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { [[ -n "$_SKIPPING" ]] || printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { [[ -n "$_SKIPPING" ]] || printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
good() { [[ -n "$_SKIPPING" ]] || printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# open_url URL opens it in the developer's browser, cross-platform incl. WSL.
open_url() {
  [[ -n "$_SKIPPING" ]] && return 0
  local url="$1"
  if [[ -n "$NO_BROWSER" ]]; then
    printf '  %s↗ open%s %s\n' "$GREEN" "$RESET" "$url"; return 0
  fi
  # A walk returns to the same page many times: one wizard opens 5 pages across
  # 35 calls. Opening each time buries the reviewer in duplicate tabs, so a URL
  # already opened this run is named instead. --reopen restores every open.
  if [[ -z "$REOPEN" ]]; then
    local opened=" ${_OPENED[*]-} "
    if [[ "$opened" == *" $url "* ]]; then
      printf '  %s↗ already open%s %s\n' "$DIM" "$RESET" "$url"
      return 0
    fi
  fi
  _OPENED+=("$url")
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the developer to finish the manual part.
pause() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. Put it before any
# step that changes data.
confirm() {
  [[ -n "$_SKIPPING" ]] && return 1
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# check "expected" states the Then and records pass, fail or skip for the
# current stage. Every verdict takes a one-line note; a skip asks again until
# it has a reason. q saves the rows so far and ends the walk.
check() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s✔ Expected:%s %s\n' "$BOLD" "$RESET" "$1"
  local verdict="" reply="" note_text="" colour=""
  while [[ -z "$verdict" ]]; do
    printf '  %s? pass / fail / skip / quit [p/f/s/q]%s ' "$YELLOW" "$RESET"
    # End of input records a skip, so a piped run never spins.
    if ! read -r reply; then verdict="skip"; break; fi
    case "${reply//[[:space:]]/}" in
      [pP]*) verdict="pass" ;;
      [fF]*) verdict="fail" ;;
      [sS]*) verdict="skip" ;;
      [qQ]*) finish; exit 0 ;;
    esac
  done
  local label="Note (optional):"
  [[ "$verdict" == "skip" ]] && label="Why skipped:"
  while :; do
    printf '  %s%s%s ' "$BOLD" "$label" "$RESET"
    read -r note_text || { note_text=""; break; }   # end of input keeps an empty reason
    [[ "$verdict" != "skip" || -n "${note_text//[[:space:]]/}" ]] && break
  done
  case "$verdict" in
    pass) colour="$GREEN" ;;
    fail) colour="$RED" ;;
    *)    colour="$YELLOW" ;;
  esac
  printf '  %s%s%s\n' "$colour" "$verdict" "$RESET"
  RECORDS+=("$(printf '%s\t%s\t%s\t%s' "$_STAGE_ID" "$1" "$verdict" "$note_text")")
}

# finish clears, writes the results table and shows the closing summary. On an
# --only run, rows for stages not walked this time are kept from the previous
# file. Exit code is 1 when any check failed.
finish() {
  local rows=() line id record r_id r_check r_result r_note
  local pass=0 fail=0 skip=0

  # An id that names no stage silently filters every stage out, and the walk
  # then reports success having checked nothing. Refuse before the results file
  # is written, so a mistyped id never overwrites the rows of a good run.
  if [[ -n "$ONLY" ]]; then
    # Join under the default IFS, because ${_SEEN[*]} separates on the first
    # character of IFS and the split below needs IFS to be a comma.
    local seen=" ${_SEEN[*]-} "
    local -a missing=()
    local want
    local IFS=,
    for want in $ONLY; do
      [[ "$seen" == *" $want "* ]] || missing+=("$want")
    done
    unset IFS
    if [[ ${#missing[@]} -gt 0 ]]; then
      printf '%s\n' "no stage in this wizard is named: ${missing[*]}" >&2
      exit 2
    fi
  fi

  if [[ -n "$ONLY" && -f "$RESULTS" ]]; then
    while IFS= read -r line; do
      [[ "$line" == '| '* ]] || continue
      id="${line#| }"; id="${id%% |*}"
      [[ "$id" == "Id" || "$id" == "---" ]] && continue
      _excluded "$id" && rows+=("$line")
    done < "$RESULTS"
  fi

  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    rows+=("| $r_id | ${r_check//|/\\|} | $r_result | ${r_note//|/\\|} |")
  done

  for line in ${rows[@]+"${rows[@]}"}; do
    case "$line" in
      *"| pass |"*) pass=$((pass + 1)) ;;
      *"| fail |"*) fail=$((fail + 1)) ;;
      *"| skip |"*) skip=$((skip + 1)) ;;
    esac
  done

  local walk_note=""
  printf '  %sNote for the whole walk (optional):%s ' "$BOLD" "$RESET"
  read -r walk_note || true

  {
    printf '# QA walk results\n\n'
    printf -- '- **Run**: %s\n' "$(date '+%Y-%m-%d %H:%M')"
    printf -- '- **Result**: %s pass, %s fail, %s skip\n' "$pass" "$fail" "$skip"
    [[ -n "${walk_note//[[:space:]]/}" ]] && printf -- '- **Note**: %s\n' "$walk_note"
    printf '\n'
    printf '| Id | Check | Result | Note |\n|---|---|---|---|\n'
    for line in ${rows[@]+"${rows[@]}"}; do printf '%s\n' "$line"; done
  } > "$RESULTS"

  _clear
  printf '\n'
  if [[ "$fail" -gt 0 ]]; then
    printf '%s%s  ✗ %s check(s) failed%s\n' "$BOLD" "$RED" "$fail" "$RESET"
  else
    printf '%s%s  ✓ Walk complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  printf '%s  %s pass, %s fail, %s skip · written to %s%s\n' \
    "$DIM" "$pass" "$fail" "$skip" "$RESULTS" "$RESET"
  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    [[ "$r_result" == "pass" ]] && continue
    printf '  %s- %s %s: %s%s\n' "$DIM" "$r_id" "$r_result" "$r_note" "$RESET"
  done
  printf '\n'
  [[ "$fail" -gt 0 ]] && exit 1
  return 0
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per check, in the confirmed order.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=19

BASE="${KCC_BASE_URL:-https://localhost:58671}"

JS_FRESH="document.cookie='kcc-visit=; max-age=0; path=/'; location.reload()"
JS_BACK() {
  printf "document.cookie='kcc-visit=1.'+document.cookie.match(/kcc-visit=1\\\\.([0-9a-f]+)/)[1]+'.'+(Math.floor(Date.now()/1000)-%s)+'; max-age=1800; path=/; secure; samesite=lax'; location.reload()" "$1"
}
JS_THEME_DARK="document.documentElement.dataset.theme='dark'"
JS_THEME_LIGHT="document.documentElement.dataset.theme='light'"
JS_OPACITY="[...document.querySelectorAll('.kcc-wash')].map(w=>getComputedStyle(w).opacity)"
JS_FILTERS="[...document.querySelectorAll('.kcc-wash, .kcc-wash *')].map(e=>getComputedStyle(e).filter).filter(f=>f!=='none').length"
JS_CUT="(r=>r)([...document.querySelectorAll('.kcc-washes')].map(f=>{const b=f.getBoundingClientRect();return [...f.children].map(w=>{const r=w.getBoundingClientRect();return r.left<b.left||r.top<b.top||r.right>b.right||r.bottom>b.bottom}).filter(Boolean).length+'/'+f.children.length}))"

visit_at() {
  step "Open devtools Console on this page and run:"
  note "  $(JS_BACK "$1")"
  note "  (back-dates the visit start by $1 s; the page reloads)"
}

banner "QA walk: Crayon wash texture"

note "Prerequisites: site running at $BASE (set KCC_BASE_URL to change it), built with yarn build:all."
note "The library needs recipes: POST $BASE/api/dev/seed-recipes in Development seeds 25 of them."
note "Judge every visual stage in light and dark (toggle the ramp, or run: $JS_THEME_DARK)."
note "Reference looks: pre-006 captures from 006, after-006 captures in tests/results/perf/captures/main."
note "Use a normal (non-private) window, with devtools open. Check Chromium and WebKit (Safari) where noted."
pause "Press Enter to begin."

# ── Look: fully bloomed pages ──────────────────────────────────────────────
stage "US1-1" "Light ramp: short chalk strokes, lobed ragged outline, no darker ring"
say "Given a fully bloomed visit in the light ramp."
open_url "$BASE/recipes"
visit_at 1800
step "Run: $JS_THEME_LIGHT   (or toggle to light)"
step "Look at each wash on /recipes, then on / and a recipe page, up close and from arm's length."
note "Compare with specs/007-crayon-wash-texture/mockups/wash-light.jpg."
check "Each wash shows short chalk strokes and a lobed, ragged outline that fades out, and no wash shows a smooth fill with a darker ring at its edge."

stage "US1-2" "Dark ramp: same chalk, nothing reads as fur, text meets AA"
say "Given the same fully bloomed visit in the dark ramp."
open_url "$BASE/recipes"
step "Run: $JS_THEME_DARK   (or toggle to dark)"
step "Look at the same pages; read the text that sits on a wash."
note "Compare with specs/007-crayon-wash-texture/mockups/wash-dark.jpg. Thin dark strands on the lit fill are the fur to look for."
check "The washes show the same chalk strokes, nothing reads as fur, and every text on them still meets WCAG AA."

stage "US1-3" "Most washes are cut by a sheet edge"
say "Given a fully bloomed visit, any ramp."
open_url "$BASE/recipes"
step "Look at the washes on each sheet of /recipes, a recipe page and /."
check "Most of a sheet's washes are cut by an edge of the sheet, and a wash seldom shows as a whole circle."

stage "US1-4" "A wash part way through its bloom already carries the texture"
say "Given a visit early in its bloom."
open_url "$BASE/recipes"
visit_at 120
step "Look at washes that are still growing (opacity between 0 and its peak). Run: $JS_OPACITY"
check "A wash part way through its steps shows the same texture at its current size, not a smooth spot that gains texture later."

# ── Look rounds ────────────────────────────────────────────────────────────
stage "US2-1" "Look round showed three directions beside pre-006 and after-006"
say "Given the look round records in the spec folder."
step "Open specs/007-crayon-wash-texture/mockups/README.md and wash.html (served from .mockups/007-crayon-wash-texture/)."
check "The look round shows at least the three chosen directions (faithful 005 restore, dark rim dropped, pencil tooth) beside the pre-006 and after-006 looks, on the same pages and the same visit state."

stage "US2-2" "Rounds continued until the owner approved one"
say "Given the owner asked for mixes and changes."
step "Read 'Rounds, and why the other options lost' in mockups/README.md."
check "Each next round shows the revised candidate, and rounds continue until the owner approves one; the approved look is recorded in the spec folder."

# ── Performance ────────────────────────────────────────────────────────────
stage "US3-1" "Perf harness: every budget and guard passes"
say "Given the chosen texture built with yarn build:all and a Release build."
warn "Long run: the full matrix takes a while. Skip here and record the result from a prior run if you have one."
step "Run: yarn perf --check   (repository root)"
step "Run: dotnet run --project tests/KCC.E2ETests/KCC.E2ETests.csproj -c Release -- --treenode-filter \"/*/*/DeterministicGuardTests/*\""
step "Compare with tests/results/perf/main.json; a flipped case is re-run with KCC_PERF_RUNS=3 and judged on its median."
check "The 006 harness runs locally and in CI, and every budget and guard that passes on main passes in both engines, both ramps and both profiles."

stage "US3-2" "Scripts off: first paint matches scripts on"
say "Given scripts turned off."
open_url "$BASE/recipes"
step "In devtools Command menu run 'Disable JavaScript', reload and look at the washes; then re-enable and reload."
check "The washes match the scripts-enabled first paint."

# ── Edge cases ─────────────────────────────────────────────────────────────
stage "EC-1" "Small wash on a narrow card"
say "Given a fully bloomed visit and phone width (about 340 px)."
open_url "$BASE/recipes"
step "Emulate a phone, then look at the smallest recipe card washes up close."
check "The texture keeps its grain and edge at small sizes and never collapses into a flat or blurred dot."

stage "EC-2" "Two washes overlapping at their peak"
say "Given a sheet where two washes overlap, fully bloomed, in both ramps."
open_url "$BASE/recipes"
step "Find an overlap, read text over it, and look for the lower wash's strokes through the upper one."
check "The stack keeps text readable in both ramps, and the texture of the lower wash stays visible through the upper one."

stage "EC-3" "Chromium and WebKit both read as crayon"
say "Given the same page in Chromium and in Safari."
open_url "$BASE/recipes"
step "Compare the washes in each engine, both ramps."
check "The chosen look reads as crayon in both."

stage "EC-4" "Reduced motion"
say "Given prefers-reduced-motion: reduce."
open_url "$BASE/recipes"
step "In devtools Rendering panel, set 'Emulate CSS prefers-reduced-motion: reduce' and reload."
check "Washes rest at their bloomed state with the same texture."

stage "EC-5" "High-density screen"
say "Given a DPR 2 display (or devtools device pixel ratio 2) against DPR 1."
open_url "$BASE/recipes"
step "Compare grain size at DPR 1 and DPR 2."
check "The texture holds its grain size rather than turning smooth when scaled."

stage "EC-6" "Neighbouring sheets never repeat a wash shape at the same place"
say "Given a page with several adjacent sheets."
open_url "$BASE/recipes"
step "Compare washes of neighbouring cards at the same position."
check "Two neighbouring sheets never show the same wash shape at the same place."

stage "EC-7" "A sliver wash on a small card still reads as a wash"
say "Given a small card whose wash centre lies past the edge."
open_url "$BASE/recipes"
step "Look for cards where only a sliver of a wash shows."
check "It still shows enough colour to read as a wash."

stage "EC-8" "Wide reading sheet with four washes"
say "Given a fully bloomed recipe page."
open_url "$BASE/recipes"
step "Open a recipe from the list and look at the wide reading sheet."
check "The pair cap may keep one wash smaller than the rest; no point lies under more than two washes."

# ── Success criteria ───────────────────────────────────────────────────────
stage "SC-001" "Owner approves as chalk, not moldy or furry"
say "Given the built site, both ramps, both engines, both profiles (desktop and phone)."
open_url "$BASE/"
step "Walk /, /recipes, a recipe page and /account/login at a fully bloomed visit; compare with the approved round (mockups/wash-light.jpg and wash-dark.jpg)."
check "The owner approves the built washes as chalk and not moldy or furry."

stage "SC-005" "Scripts-disabled first paint matches scripts-enabled on every page type"
say "Given scripts off, then on."
open_url "$BASE/"
step "On /, /recipes, a recipe page, /account/login and /error/404, compare first paint with scripts disabled and enabled."
check "Every scripts-disabled first paint matches its scripts-enabled one."

stage "SC-007" "At least three quarters of washes are cut by an edge"
say "Given a fully bloomed visit on each page type."
open_url "$BASE/recipes"
step "Run: $JS_CUT   (washes whose box leaves the field; a rough count, the padded box overstates it)"
step "Judge by eye as well: count washes whose ink runs off a sheet edge."
note "The spec counts a wash as cut when its drawn blob's ellipse crosses the field's edge (A23)."
check "At least three quarters of the washes are cut by an edge of their sheet."

finish
